// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint96 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));

        address owner = address(0); // placeholder, will be set after first call
        // Since we cannot read owner directly, we use vm.prank to fund the contract
        vm.deal(address(c), 1 ether);

        // Record balances before
        uint256 balanceBeforeReceiver = receiver.balance;
        uint256 balanceBeforeContract = address(c).balance;

        // Call as owner - we need to know who owner is; we'll infer it's the caller (deployer)
        // Actually, we can prank as the deployer
        vm.prank(address(this));
        c.sendTo(receiver, amount);

        uint256 balanceAfterReceiver = receiver.balance;
        uint256 balanceAfterContract = address(c).balance;

        // The rule: receiver gains `amount`, contract loses `amount`
        assertTrue(balanceAfterReceiver == balanceBeforeReceiver + amount);
        assertTrue(balanceAfterContract == balanceBeforeContract - amount);
    }
}

