pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(this));
        vm.assume(amount <= address(this).balance);

        address originalReceiver = address(0x1234);

        // Record the caller's balance before the call
        uint256 callerBalanceBefore = caller.balance;

        // Attempt to call sendTo as the given caller
        vm.prank(caller);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("sendTo(address,uint256)", originalReceiver, amount));

        // The general rule: After any call to sendTo, the caller's balance should not change (since only owner can send, and owner is hardcoded as deployer)
        // If caller is not owner, the call reverts (no balance change)
        // If caller is owner, the call succeeds but the caller's balance decreases by amount + gas (gas is negligible for this check)
        // The rule we assert: The caller's address cannot be modified by the contract's state; only the owner is allowed to send
        // Since owner is not the caller in general, the rule is that caller's balance remains same if call reverts
        if (!success) {
            assertTrue(caller.balance == callerBalanceBefore);
        } else {
            // If call succeeded, caller must be the owner (address(this))
            assertTrue(caller == address(this));
        }
    }
}

